(function(){
'use strict';
const dialog=document.getElementById('destinationDialog'),root=document.getElementById('destinationGuide');
if(!dialog||!root)return;
const esc=value=>String(value||'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const readSaved=()=>{try{const value=JSON.parse(localStorage.getItem('safariPocketbookSavedPlaces')||'[]');return Array.isArray(value)?value:[]}catch(error){return[]}};
function atlasPlace(name,country){const row=(window.africanAtlas||[]).find(item=>item[0]===country),region=row?.[1]||'Africa';return{name,countryName:country,region,type:'Pocketbook destination',tags:[]}}
function resolve(name,country=''){const clean=String(name||'').split(',')[0].trim(),known=[...(window.safariPlaces||[]),...(window.botswanaPlaces||[])].find(item=>item.name.toLowerCase()===clean.toLowerCase());return known||atlasPlace(clean,country||String(name||'').split(',').slice(1).join(',').trim())}
function toast(message){const node=document.getElementById('toast');if(!node)return;node.textContent=message;node.classList.add('show');setTimeout(()=>node.classList.remove('show'),2200)}
function close(){dialog.close()}
function openMap(place){close();window.openPocketbookView?.('map');setTimeout(()=>{const input=document.getElementById('mapSearch');if(!input)return;input.value=`${place.name}, ${place.countryName}`;input.dispatchEvent(new Event('input',{bubbles:true}));input.focus()},100)}
function openWildlife(place){close();window.openPocketbookView?.('field');if(!place.code)return;setTimeout(()=>{document.querySelector('#faunaMode [data-mode="database"]')?.click();const select=document.getElementById('faunaCountry');if(select){select.value=place.code;select.dispatchEvent(new Event('change',{bubbles:true}))}},80)}
function save(place){const saved=readSaved();if(saved.some(item=>item.name===place.name)){toast('This destination is already saved.');return}saved.push({name:place.name,countryName:place.countryName,type:place.type,savedAt:new Date().toISOString()});localStorage.setItem('safariPocketbookSavedPlaces',JSON.stringify(saved));window.dispatchEvent(new Event('safari-journal-changed'));toast(`${place.name} saved to your Journal.`)}
window.openDestinationGuide=(name,country='')=>{const place=resolve(name,country);if(!place.name)return;root.innerHTML=`<header class="destination-hero"><p class="eyebrow">DESTINATION POCKETBOOK</p><h2>${esc(place.name)}</h2><p>${esc(place.countryName)} · ${esc(place.type)}</p></header><section class="destination-summary"><div><small>Country</small><strong>${esc(place.countryName)}</strong></div><div><small>Region</small><strong>${esc(place.region||'Africa')}</strong></div>${place.tags?.length?`<div class="destination-tags">${place.tags.map(tag=>`<span>${esc(tag)}</span>`).join('')}</div>`:''}</section>${place.context?`<section class="destination-place-context"><p class="eyebrow dark">LOCAL CONTEXT</p><h3>${esc(place.parentRegion||place.name)}</h3><p><strong>Area:</strong> ${esc(place.context)}</p><p><strong>Experiences indexed:</strong> ${esc(place.experiences)}</p></section>`:""}<section class="destination-tools"><p class="eyebrow dark">YOUR FIELD DESK</p><h3>Everything connected to this place</h3><div class="destination-action-grid"><button data-destination-action="map">⌖<span><strong>Map &amp; location</strong><small>Open the exact geographic workspace</small></span></button><button data-destination-action="country">▱<span><strong>Country guide</strong><small>Essentials, languages and planning</small></span></button><button data-destination-action="wildlife">◉<span><strong>Wildlife guide</strong><small>Browse the country field guide</small></span></button><button data-destination-action="health">✚<span><strong>Travel &amp; health</strong><small>Open current official-source tools</small></span></button><button data-destination-action="stay">⌂<span><strong>Flights &amp; stays</strong><small>Continue to the journey desk</small></span></button><button data-destination-action="journal">＋<span><strong>Save destination</strong><small>Keep it in your private Journal</small></span></button></div></section><section class="destination-integrity"><strong>Destination companion</strong><p>This entry connects the Pocketbook’s map, country reference, wildlife, language, health, planning and journal tools. Current access, permits, operating status, prices and availability must come from their live or official sources.</p></section>`;dialog.dataset.name=place.name;dialog.dataset.country=place.countryName;dialog.showModal();root.querySelector('[data-destination-action="map"]')?.addEventListener('click',()=>openMap(place));root.querySelector('[data-destination-action="country"]')?.addEventListener('click',()=>{close();window.openCountryBrief?.(place.countryName)});root.querySelector('[data-destination-action="wildlife"]')?.addEventListener('click',()=>openWildlife(place));root.querySelector('[data-destination-action="health"]')?.addEventListener('click',()=>{close();window.openTravelHealth?.(place.countryName)});root.querySelector('[data-destination-action="stay"]')?.addEventListener('click',()=>{close();window.openPocketbookView?.('bookings');setTimeout(()=>{document.querySelector('[data-booking-tab="stay"]')?.click();const input=document.getElementById('stayDestination');if(input){input.value=place.name;input.focus()}},80)});root.querySelector('[data-destination-action="journal"]')?.addEventListener('click',()=>save(place))};
document.querySelector('.destination-close')?.addEventListener('click',close);dialog.querySelector('.dialog-sos-shortcut')?.addEventListener('click',()=>document.getElementById('sosButton')?.click());
document.addEventListener('click',event=>{const button=event.target.closest('[data-destination-guide]');if(button)window.openDestinationGuide(button.dataset.destinationGuide,button.dataset.destinationCountry||'')});
})();
